runner=OBS/'run_observer41_tests.py'
cp=subprocess.run([sys.executable,'-B',str(runner)],cwd=str(OBS),check=False)
if cp.returncode:
    raise SystemExit('STOP: OBS4.1 tests failed. Do not start observer41; backups remain available.')
